const u=n=>{const t=Number(n);return Number.isFinite(t)?t:0},x=n=>Math.round(u(n)*100),f=n=>n/100;function c(n){return f(x(n))}function I(n,t){return x(n)>x(t)}function m(n,t){const e=x(n),o=1+u(t)/100,s=o>0?Math.round(e/o):e;return f(s)}function A(n,t){const e=x(n),r=u(t),o=Math.round(e*r/100);return f(e+o)}function d(n,t,e,r){const o=u(n);return e===r?c(o):e==="tax_exclusive"&&r==="tax_inclusive"?A(o,t):m(o,t)}function C(n,t,e,r){const o=u(n);if(e==="tax_inclusive"){const i=c(o),v=m(i,t);return{invoiceAmountExcl:v,totalIncl:i,taxAmount:c(i-v)}}const s=c(o);let l=A(s,t);const a=r?.maxTotalIncl;if(a!=null&&Number.isFinite(a)&&a>=0){const i=c(a),v=c(l-i);if(l>i&&v<=.01){const E=m(i,t);return{invoiceAmountExcl:E,totalIncl:i,taxAmount:c(i-E)}}}return{invoiceAmountExcl:s,totalIncl:l,taxAmount:c(l-s)}}function b(n,t,e,r){const o=u(n),s=u(t),l=u(e);if(!(o>0)||s===l||r==="tax_inclusive")return c(o);const a=A(o,s);return m(a,l)}function F(n,t,e){if(u(n)>0)return e==="tax_exclusive"?c(n):m(n,t)}export{b as a,F as b,d as c,m as i,I as m,C as r};
